const motivo = $("receber").first().json.motivo;
const user_id = $("receber").first().json.user_id;
const conversation_id = $("receber").first().json.conversation_id;
const id_registro = $("receber").first().json.id_registro;

const user = $('Get user').first().json;
const properties = user.properties;

const manager = properties.find(p => p.name === "managerId");
const broker = properties.find(p => p.name === "userId");

const user_id_brokers = manager?.value || broker?.value || null;
const email = user.email || null;

return { motivo, user_id, conversation_id, user_id_brokers, id_registro, email };

const grupo_retencao = ["financeiro", "usabilidade", "dados"]

const motivo = $("gather info").first().json.motivo?.toLowerCase()

const grupo = grupo_retencao.includes(motivo) ? "grupo_retencao" : "grupo_cancelamento"

return {grupo}

const vigencia_fim = $("get-user-sub").first().json.final // formato: yyyy-mm-dd

const now = new Date()
const fim = new Date(vigencia_fim)

let classificacao = ""

if (now > fim) {
  classificacao = "vigencia encerrada"
} else {
  const diffEmMs = fim - now
  const umMesEmMs = 30 * 24 * 60 * 60 * 1000

  if (diffEmMs <= umMesEmMs) {
    classificacao = "falta menos de 1 mês"
  } else {
    classificacao = "vigencia maior que 1 mês"
  }
}

return { classificacao, vigencia_fim }

const grupo_retencao = ["financeiro", "usabilidade", "dados"]

const motivo = $("gather info").first().json.motivo?.toLowerCase()

const grupo = grupo_retencao.includes(motivo) ? "grupo_retencao" : "grupo_cancelamento"

return {grupo}

